<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Check, Cloud, Database, File, HardDrive, Pencil, Plus, RefreshCw, ShieldCheck, Trash2, X } from 'lucide-vue-next'
import { api, applyUploadLimit, saveAdminSettings, size } from '../api'
import type { Overview, Provider, Settings } from '../types'
import AdminFiles from '../components/AdminFiles.vue'
import AdminUsers from '../components/AdminUsers.vue'
import { GIB, MIB, parseUploadLimit, uploadLimitInput } from '../uploadPolicy'
import type { UploadSizeUnit } from '../uploadPolicy'
const tab = ref<'overview' | 'files' | 'users' | 'storage' | 'settings'>('overview'); const overview = ref<Overview>(); const providers = ref<Provider[]>([]); const capacityGiB = ref(10); const threshold = ref(50); const loading = ref(true); const busy = ref(false); const error = ref(''); const success = ref(''); const providerOpen = ref(false); const editing = ref<string | null>(null); const deleteProvider = ref<Provider | null>(null); const reloadKey = ref(0)
const emptyProvider = () => ({ name: '', type: 'S3' as Provider['type'], endpoint: '', region: 'us-east-1', bucket: '', mountPath: '', mountId: '', accessKey: '', secretKey: '', enabled: true, priority: 100 })
const form = reactive(emptyProvider())
const uploadLimitValue = ref<number | string>(1); const uploadLimitUnit = ref<UploadSizeUnit>('GiB')
const uploadLimitMin = computed(() => uploadLimitUnit.value === 'GiB' ? MIB / GIB : 1)
const uploadLimitMax = computed(() => uploadLimitUnit.value === 'GiB' ? 100 : 100 * GIB / MIB)
const usage = computed(() => overview.value ? Math.min(100, Math.round(overview.value.localUsedBytes / overview.value.localCapacityBytes * 1000) / 10) : 0)
function fail(e: unknown) { error.value = (e as Error).message }
async function load() { loading.value = true; error.value = ''; try { const result = await Promise.all([api<Overview>('/admin/overview'), api<Provider[]>('/admin/providers'), api<Settings>('/admin/settings')]); overview.value = result[0]; providers.value = result[1]; capacityGiB.value = result[2].localCapacityBytes / 1024 ** 3; threshold.value = result[2].offloadThreshold; const limit = uploadLimitInput(result[2].maxUploadBytes); uploadLimitValue.value = limit.value; uploadLimitUnit.value = limit.unit; applyUploadLimit(result[2].maxUploadBytes); reloadKey.value++ } catch (e) { fail(e) } finally { loading.value = false } }
async function updateOverview() { try { overview.value = await api<Overview>('/admin/overview') } catch (e) { fail(e) } }
async function maintenance() { busy.value = true; error.value = ''; success.value = ''; try { const result = await api<{ message: string }>('/admin/maintenance', { method: 'POST' }); success.value = result.message; await load() } catch (e) { fail(e) } finally { busy.value = false } }
async function saveSettings() { if (busy.value) return; busy.value = true; error.value = ''; success.value = ''; try { const maxUploadBytes = parseUploadLimit(uploadLimitValue.value, uploadLimitUnit.value); await saveAdminSettings({ localCapacityBytes: Math.round(capacityGiB.value * 1024 ** 3), offloadThreshold: threshold.value, maxUploadBytes }); success.value = '存储与上传设置已保存'; await load() } catch (e) { fail(e) } finally { busy.value = false } }
function openProvider(provider?: Provider) { error.value = ''; editing.value = provider?.id || null; Object.assign(form, emptyProvider(), provider ? { name: provider.name, type: provider.type || 'S3', endpoint: provider.endpoint || '', region: provider.region || 'us-east-1', bucket: provider.bucket || '', mountPath: provider.mountPath || '', mountId: provider.mountId || '', enabled: provider.enabled, priority: provider.priority } : {}); providerOpen.value = true }
function closeProvider() { if (busy.value) return; providerOpen.value = false; form.accessKey = ''; form.secretKey = ''; error.value = '' }
async function saveProvider() { busy.value = true; error.value = ''; success.value = ''; try { const body = form.type === 'S3' ? { ...form, mountPath: null, mountId: null } : { ...form, endpoint: null, region: null, bucket: null, accessKey: null, secretKey: null }; await api(`/admin/providers${editing.value ? `/${editing.value}` : ''}`, { method: editing.value ? 'PUT' : 'POST', body: JSON.stringify(body) }); providerOpen.value = false; form.accessKey = ''; form.secretKey = ''; success.value = '存储器配置已保存'; await load() } catch (e) { fail(e) } finally { busy.value = false } }
async function removeProvider() { if (!deleteProvider.value) return; busy.value = true; error.value = ''; try { await api(`/admin/providers/${deleteProvider.value.id}`, { method: 'DELETE' }); deleteProvider.value = null; success.value = '存储器已移除'; await load() } catch (e) { fail(e) } finally { busy.value = false } }
onMounted(load)
</script>
<template>
  <div class="page-width content-page admin-page"><div class="page-title"><div><div class="eyebrow"><ShieldCheck :size="15" />ADMIN CONSOLE</div><h1>管理后台</h1><p class="muted">看清每一份空间，管理每一次分享。</p></div><button class="button button-outline" :disabled="loading || busy" @click="load"><RefreshCw :size="16" />刷新数据</button></div>
    <div class="admin-tabs" role="tablist" aria-label="管理功能"><button role="tab" :aria-selected="tab === 'overview'" :class="{ active: tab === 'overview' }" @click="tab = 'overview'">概览</button><button role="tab" :aria-selected="tab === 'files'" :class="{ active: tab === 'files' }" @click="tab = 'files'">文件管理</button><button role="tab" :aria-selected="tab === 'users'" :class="{ active: tab === 'users' }" @click="tab = 'users'">用户管理</button><button role="tab" :aria-selected="tab === 'storage'" :class="{ active: tab === 'storage' }" @click="tab = 'storage'">远端存储</button><button role="tab" :aria-selected="tab === 'settings'" :class="{ active: tab === 'settings' }" @click="tab = 'settings'">容量设置</button></div>
    <div v-if="error && !providerOpen && !deleteProvider" class="notice error" role="alert">{{ error }}<button class="icon-button" aria-label="关闭错误" @click="error = ''"><X :size="16" /></button></div><div v-if="success" class="notice success" role="status">{{ success }}<button class="icon-button" aria-label="关闭提示" @click="success = ''"><X :size="16" /></button></div>
    <div v-if="loading" class="empty-state"><span class="spinner"></span>正在读取管理数据…</div>
    <template v-else-if="overview">
      <template v-if="tab === 'overview'"><div class="stats-grid"><article class="stat-card"><span class="stat-label"><HardDrive :size="17" />本地已用</span><strong>{{ size(overview.localUsedBytes) }}</strong><small>共 {{ size(overview.localCapacityBytes) }} 可规划空间</small></article><article class="stat-card"><span class="stat-label"><Cloud :size="17" />远端已用</span><strong>{{ size(overview.remoteUsedBytes) }}</strong><small>{{ overview.enabledProviders }} 个存储器已启用</small></article><article class="stat-card"><span class="stat-label"><File :size="17" />文件总数</span><strong>{{ overview.totalFiles.toLocaleString() }}</strong><small>{{ overview.permanentFiles }} 个文件永久保存</small></article></div><section class="panel capacity-panel"><div class="panel-header"><h2>本地存储空间</h2><span class="badge badge-teal">已用 {{ usage }}%</span></div><div class="capacity-visual"><div class="capacity-label"><strong>{{ size(overview.localUsedBytes) }}<span> / {{ size(overview.localCapacityBytes) }}</span></strong><span class="muted">转存阈值 {{ overview.offloadThreshold }}%</span></div><div class="capacity-track"><span :style="{ width: `${usage}%` }"></span><i :style="{ left: `${overview.offloadThreshold}%` }" :title="`转存阈值 ${overview.offloadThreshold}%`"></i></div><p>本地使用量达到阈值后，系统会将较早上传的文件转存至可用的远端存储器。</p></div></section><section class="panel maintenance-panel"><span class="benefit-icon"><RefreshCw :size="22" /></span><div><h2>文件自动维护</h2><p>清理到期文件，并按容量阈值执行远端转存。任务会在后台定时运行。</p></div><button class="button button-outline" :disabled="busy" @click="maintenance">{{ busy ? '正在维护…' : '立即执行维护' }}</button></section></template>
      <AdminFiles v-if="tab === 'files'" :key="`files-${reloadKey}`" @changed="updateOverview" />
      <AdminUsers v-if="tab === 'users'" :key="`users-${reloadKey}`" />
      <template v-if="tab === 'storage'"><div class="section-toolbar"><p>连接 S3、NFS 或 SMB 存储，按优先级自动转存。</p><button class="button button-primary" @click="openProvider()"><Plus :size="17" />添加存储器</button></div><div v-if="!providers.length" class="panel empty-state"><Cloud :size="42" :stroke-width="1.3" /><h3>连接你的第一个远端存储器</h3><p>支持 S3 兼容服务，以及已挂载到服务器的 NFS、SMB 共享。<br>未配置远端存储时，文件仅保存在本地，达到本地配额后停止接收上传。</p><button class="button button-outline" @click="openProvider()">添加存储器</button></div><div v-else class="provider-grid"><article v-for="provider in providers" :key="provider.id" class="panel provider-card"><div class="provider-title"><span class="benefit-icon"><Database :size="22" /></span><div class="stacked-badges"><span class="badge badge-neutral">{{ provider.type || 'S3' }}</span><span class="badge" :class="provider.enabled ? 'badge-teal' : 'badge-neutral'">{{ provider.enabled ? '已启用' : '已停用' }}</span></div></div><h2>{{ provider.name }}</h2><dl><template v-if="!provider.type || provider.type === 'S3'"><div><dt>服务地址</dt><dd>{{ provider.endpoint }}</dd></div><div><dt>存储桶</dt><dd>{{ provider.bucket }}</dd></div><div><dt>区域</dt><dd>{{ provider.region }}</dd></div></template><template v-else><div><dt>挂载路径</dt><dd>{{ provider.mountPath }}</dd></div><div><dt>挂载标识</dt><dd>{{ provider.mountId }}</dd></div></template><div><dt>优先级</dt><dd>{{ provider.priority }} <span class="muted">（数值越小越优先）</span></dd></div></dl><div class="provider-actions"><button class="text-button" @click="openProvider(provider)"><Pencil :size="15" />编辑配置</button><button class="icon-button danger" aria-label="移除存储器" @click="deleteProvider = provider; error = ''"><Trash2 :size="17" /></button></div></article></div><p class="page-note">已有文件的存储器无法删除。S3 凭据加密保存；NFS / SMB 由服务器操作系统挂载，应用不保存共享账号密码。</p></template>
      <section v-if="tab === 'settings'" class="panel settings-panel"><div class="panel-header"><h2>存储容量与上传策略</h2></div><form class="settings-form" @submit.prevent="saveSettings"><label class="field">规划本地存储容量<div class="input-unit"><input v-model.number="capacityGiB" type="number" min="0.001" max="1048576" step="0.001" required><span>GB</span></div><small>按 1 GB = 1024³ 字节计算。此设置是应用配额，实际磁盘仍需预留足够空间。</small></label><label class="field">开始转存的使用率<div class="input-unit"><input v-model.number="threshold" type="number" min="10" max="90" step="1" required><span>%</span></div><small>默认 50%。达到阈值后，优先将较早上传的文件转存到远端。</small></label><label class="field">单文件上传上限<div class="upload-limit-input"><input v-model.number="uploadLimitValue" type="number" :min="uploadLimitMin" :max="uploadLimitMax" step="any" required aria-label="单文件上传上限数值"><select v-model="uploadLimitUnit" aria-label="单文件上传上限单位"><option value="MiB">MiB</option><option value="GiB">GiB</option></select></div><small>范围 1 MiB–100 GiB，默认 1 GiB。保存后对新上传生效，已有文件不受影响。文件先写入本地，仍受本地配额和实际可用磁盘空间限制。</small></label><div class="notice info"><HardDrive :size="19" /><span>文件先保存在本地。远端写入成功并校验后才清除本地副本；远端不可用时保留本地文件，等待下次重试。</span></div><button class="button button-primary" :disabled="busy">{{ busy ? '正在保存…' : '保存设置' }}<Check :size="17" /></button></form></section>
    </template><div v-else class="empty-state"><p>未能读取管理数据，请检查服务连接后重试。</p><button class="button button-outline" @click="load">重新加载</button></div>
  </div>
  <div v-if="providerOpen" class="modal-backdrop" @click.self="closeProvider"><section class="modal provider-modal" role="dialog" aria-modal="true" aria-labelledby="provider-title"><div class="modal-title"><h2 id="provider-title">{{ editing ? '编辑存储器' : '添加远端存储器' }}</h2><button class="icon-button" :disabled="busy" aria-label="关闭" @click="closeProvider"><X :size="20" /></button></div><p class="muted">选择存储类型，并填写服务器可访问的连接配置。</p><form @submit.prevent="saveProvider"><div class="form-grid"><label class="field">存储器名称<input v-model="form.name" required maxlength="100" placeholder="例如：主文件存储"></label><label class="field">存储类型<select v-model="form.type"><option value="S3">S3 兼容存储</option><option value="NFS">NFS 共享</option><option value="SMB">SMB 共享</option></select></label></div>
    <template v-if="form.type === 'S3'"><label class="field">服务地址<input v-model="form.endpoint" type="url" required placeholder="https://s3.example.com"></label><div class="form-grid"><label class="field">存储桶<input v-model="form.bucket" required maxlength="255" placeholder="clipboard"></label><label class="field">区域<input v-model="form.region" required maxlength="80" placeholder="us-east-1"></label></div><label class="field">Access Key<input v-model="form.accessKey" :required="!editing" autocomplete="off" :placeholder="editing ? '留空则保留现有凭据' : '输入访问密钥'"></label><label class="field">Secret Key<input v-model="form.secretKey" type="password" :required="!editing" autocomplete="new-password" :placeholder="editing ? '留空则保留现有凭据' : '输入私有密钥'"></label></template>
    <template v-else><div class="notice info mount-help"><HardDrive :size="18" /><span>请先由运维在操作系统 / Docker 中挂载 {{ form.type }} 共享，并将容器内路径置于 <code>/mnt/remote</code> 下。应用使用挂载目录读写文件，不负责连接或挂载共享。</span></div><label class="field">容器内挂载路径<input v-model="form.mountPath" required maxlength="2048" placeholder="/mnt/remote/nas"><small>填写 backend 容器可以访问的绝对路径。</small></label><label class="field">挂载标识<input v-model="form.mountId" required maxlength="128" pattern="[A-Za-z0-9_-]+" placeholder="例如：f0e2d46b-5261-48ed-9140-35bb7d44d803"><small>在共享目录创建 <code>.clipboard-storage-id</code> 文件，内容填写与此处完全相同的标识。标识缺失或不匹配时，应用会拒绝读写，防止共享断开后写到本地目录。</small></label></template>
    <div class="form-grid"><label class="field">优先级<input v-model.number="form.priority" type="number" min="0" max="10000" required></label><label class="checkbox-field"><input v-model="form.enabled" type="checkbox">启用此存储器</label></div><div v-if="error" class="notice error" role="alert">{{ error }}</div><div class="modal-actions"><button class="button button-outline" type="button" :disabled="busy" @click="closeProvider">取消</button><button class="button button-primary" :disabled="busy">{{ busy ? '正在保存…' : '保存配置' }}</button></div></form></section></div>
  <div v-if="deleteProvider" class="modal-backdrop" @click.self="!busy && (deleteProvider = null)"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="provider-delete-title"><h2 id="provider-delete-title">移除存储器？</h2><p>确定移除“{{ deleteProvider.name }}”？仍存有文件的存储器无法移除。</p><div v-if="error" class="notice error" role="alert">{{ error }}</div><div class="modal-actions"><button class="button button-outline" :disabled="busy" @click="deleteProvider = null">取消</button><button class="button button-danger" :disabled="busy" @click="removeProvider">{{ busy ? '正在处理…' : '确认移除' }}</button></div></section></div>
</template>
